  "output": "// Everything that reads like a date or a time is written in the browser, in the
// viewer's own timezone, so that pages render the same for everybody and can be
// cached and shared between people. The server only ships raw timestamps.

const RELATIVE_DAY_LIMIT = 7 // "5 days ago" up to a week out, a plain date beyond that

const relativeFormatter = new Intl.RelativeTimeFormat("en-US", { numeric: "auto" })
const timeFormatter = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" })
const dateFormatter = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" })
const dateWithYearFormatter = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" })
const weekdayFormatter = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" })
const shortDateTimeFormatter = new Intl.DateTimeFormat("en-US", { dateStyle: "short", timeStyle: "short" })
const fullDateTimeFormatter = new Intl.DateTimeFormat("en-US", {
  weekday: "long", month: "long", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit"
})

// Longest unit first, in seconds.
const AGO_UNITS = [
  [ "year", 365 * 24 * 60 * 60 ],
  [ "month", 30 * 24 * 60 * 60 ],
  [ "day", 24 * 60 * 60 ],
  [ "hour", 60 * 60 ],
  [ "minute", 60 ]
]

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatTime(date, format = "relative", now = new Date()) {
  switch (format) {
    case "ago": return timeAgo(date, now)
    case "time": return timeFormatter.format(date)
    case "date": return formatDate(date, now)
    case "full_date": return dateWithYearFormatter.format(date)
    case "day": return weekdayFormatter.format(date)
    case "datetime": return shortDateTimeFormatter.format(date)
    case "full_datetime": return fullDateTimeFormatter.format(date)
    default: return relativeTime(date, now)
  }
}

// Renders a timestamp the way you would say it out loud: a clock time for earlier
// today, "yesterday" and "tomorrow" for the days next door, "5 days ago" and
// "in 3 days" for anything within a week, and a plain date beyond that.
export function relativeTime(date, now = new Date()) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) return date < now ? timeFormatter.format(date) : "today"
  if (days < -RELATIVE_DAY_LIMIT) return formatDate(date, now)

  return relativeFormatter.format(days, "day")
}

// Renders elapsed time in words, like "2 hours ago", for timestamps that are
// always in the past.
export function timeAgo(date, now = new Date()) {
  const seconds = Math.max(0, Math.round((now - date) / 1000))
  const [ unit, unitLength ] = AGO_UNITS.find(([ , length ]) => seconds >= length) || [ "second", 1 ]

  return relativeFormatter.format(-Math.floor(seconds / unitLength), unit)
}

// Renders whatever a bridge attribute carries as a date, in the viewer's own
// timezone. Anything that isn't a timestamp is passed through untouched.
export function formatTimestamp(timestamp) {
  if (!/^\d{4}-\d{2}-\d{2}/.test(timestamp)) return timestamp

  return dateWithYearFormatter.format(new Date(timestamp))
}

function formatDate(date, now) {
  if (date.getFullYear() === now.getFullYear()) {
    return dateFormatter.format(date)
  } else {
    return dateWithYearFormatter.format(date)
  }
}
